"use client";

import { ArrowLeftIcon, ExternalLinkIcon, PencilIcon, PlusIcon } from "lucide-react";
import { useRef } from "react";

import { ActionToastProvider } from "@/components/action-toast";
import { Link } from "@/components/link";
import {
  buttonClass,
  cardClass,
  iconButtonClass,
  primaryButtonClass,
} from "@/components/plugins/customers/ui";
import { customerDisplayName } from "@/components/plugins/customers/utils";
import { projectLabels } from "@/components/plugins/projects/labels";
import { ProjectForm } from "@/components/plugins/projects/project-form";
import type {
  ProjectDetailPageProps,
  ProjectNewPageProps,
  ProjectsListProps,
  ProjectsPageProps,
} from "@/components/plugins/projects/types";
import { DeleteProject, ProjectAvatar, ProjectStatusBadge } from "@/components/plugins/projects/ui";
import { safeProjectUrl } from "@/components/plugins/projects/utils";
import { TableSearch } from "@/components/table-search";
import { cn } from "@/components/utils/cn";
import {
  tableActionCellClass,
  tableCellClass,
  tableClass,
  tableHeaderClass,
  tablePanelClass,
  tableRowClass,
} from "@/components/utils/table-styles";
import { retainRemovedItems, useOptimisticAction } from "@/components/utils/use-optimistic-action";

export type {
  Project,
  ProjectStatus,
  ProjectSection,
  ProjectFormValues,
  ProjectAssignee,
  ProjectsAppearanceProps,
  ProjectsListProps,
  ProjectsPageProps,
  ProjectDetailPageProps,
  ProjectNewPageProps,
} from "@/components/plugins/projects/types";
export type { ProjectsLabels } from "@/components/plugins/projects/labels";

const pageClass = "mx-auto w-full min-w-0 space-y-6 px-4 py-8 text-foreground";

function ProjectsListContent({
  projects: suppliedProjects,
  customers,
  assignees = [],
  customerId,
  search,
  onSearchChange,
  loading,
  error: loadError,
  createHref,
  getProjectHref,
  getCustomerHref,
  onDelete,
  labels: overrides,
  linkComponent: ProjectLink = Link,
  className,
}: ProjectsListProps) {
  const labels = { ...projectLabels, ...overrides };
  const optimistic = useOptimisticAction(suppliedProjects);
  const projects = optimistic.value;
  const error = loadError || (optimistic.error ? labels.actionError : undefined);
  const root = useRef<HTMLElement>(null);
  const visibleProjects =
    customerId === undefined
      ? projects
      : projects.filter((project) => project.ownerId === customerId);
  const owners = new Map(customers.map((customer) => [customer.id, customer]));
  const assigned = new Map(assignees.map((assignee) => [assignee.id, assignee]));
  return (
    <section
      ref={root}
      tabIndex={-1}
      aria-label={labels.title}
      className={cn(
        tablePanelClass,
        "min-w-0 space-y-5 focus-visible:ring-2 focus-visible:ring-ring",
        className,
      )}
    >
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div className="space-y-1.5">
          <h2 className="font-semibold">{labels.title}</h2>
          <p className="text-sm text-muted-foreground">
            {customerId === undefined ? labels.description : labels.customerDescription}
          </p>
        </div>
        <div className="ml-auto flex max-w-full flex-wrap items-center justify-end gap-2">
          <TableSearch
            value={search}
            onValueChange={onSearchChange}
            label={labels.search}
            placeholder={labels.searchPlaceholder}
            clearLabel={labels.clearSearch}
          />
          {createHref && (
            <ProjectLink href={createHref} className={primaryButtonClass}>
              <PlusIcon className="size-4 shrink-0" aria-hidden="true" />
              {labels.create}
            </ProjectLink>
          )}
        </div>
      </header>
      <div className="overflow-x-auto">
        <table className={tableClass} aria-busy={loading}>
          {loading && visibleProjects.length > 0 && (
            <caption className="sr-only">
              <output>{labels.loading}</output>
            </caption>
          )}
          <thead>
            <tr className={tableRowClass}>
              {[
                labels.name,
                ...(customerId === undefined ? [labels.owner] : []),
                labels.assignee,
                labels.website,
                labels.status,
                labels.actions,
              ].map((label, index) => (
                <th
                  key={index}
                  scope="col"
                  className={
                    index === (customerId === undefined ? 5 : 4)
                      ? tableActionCellClass
                      : tableHeaderClass
                  }
                >
                  {label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="[&_tr:last-child]:border-0">
            {retainRemovedItems(
              visibleProjects,
              suppliedProjects.filter(
                (row) => customerId === undefined || row.ownerId === customerId,
              ),
              optimistic.pending,
            ).map((project) => {
              const owner = owners.get(project.ownerId);
              const assignee = project.assigneeId ? assigned.get(project.assigneeId) : undefined;
              const website = safeProjectUrl(project.url);
              return (
                <tr
                  key={project.id}
                  hidden={!visibleProjects.some((row) => row.id === project.id)}
                  className={tableRowClass}
                >
                  <td className={tableCellClass}>
                    <ProjectLink
                      href={getProjectHref(project)}
                      className="font-medium hover:underline focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      {project.name}
                    </ProjectLink>
                  </td>
                  {customerId === undefined && (
                    <td className={tableCellClass}>
                      {owner ? (
                        getCustomerHref ? (
                          <ProjectLink
                            href={getCustomerHref(owner)}
                            className="hover:underline focus-visible:ring-2 focus-visible:ring-ring"
                          >
                            {customerDisplayName(owner)}
                          </ProjectLink>
                        ) : (
                          customerDisplayName(owner)
                        )
                      ) : (
                        labels.unavailableOwner
                      )}
                    </td>
                  )}
                  <td className={tableCellClass}>
                    {assignee?.name ??
                      (project.assigneeId ? labels.unavailableAssignee : labels.unassigned)}
                  </td>
                  <td className={tableCellClass}>
                    {website ? (
                      <ProjectLink
                        href={website}
                        target={website.startsWith("/") ? undefined : "_blank"}
                        rel={website.startsWith("/") ? undefined : "noopener noreferrer"}
                        aria-label={labels.visit(project.name)}
                        className={iconButtonClass}
                      >
                        <ExternalLinkIcon aria-hidden="true" />
                      </ProjectLink>
                    ) : (
                      <span className="text-muted-foreground">{labels.noWebsite}</span>
                    )}
                  </td>
                  <td className={tableCellClass}>
                    <ProjectStatusBadge status={project.status} labels={labels} />
                  </td>
                  <td className={tableActionCellClass}>
                    <div className="flex items-start justify-end gap-1">
                      <ProjectLink
                        href={getProjectHref(project)}
                        aria-label={labels.edit(project.name)}
                        className={iconButtonClass}
                      >
                        <PencilIcon className="size-4 shrink-0" aria-hidden="true" />
                      </ProjectLink>
                      {onDelete && (
                        <DeleteProject
                          project={project}
                          disabled={loading || optimistic.pending || !!loadError}
                          onDelete={(id) =>
                            optimistic.run(
                              (rows) => rows.filter((row) => row.id !== id),
                              () => onDelete(id),
                            )
                          }
                          labels={labels}
                          returnFocus={root}
                        />
                      )}
                    </div>
                  </td>
                </tr>
              );
            })}
            {((error && !loading) || visibleProjects.length === 0) && (
              <tr className={tableRowClass}>
                <td
                  colSpan={customerId === undefined ? 6 : 5}
                  className={cn(tableCellClass, "py-10 text-center text-muted-foreground")}
                >
                  {error && !loading ? (
                    <p role="alert" className="text-destructive">
                      {error}
                    </p>
                  ) : (
                    <output>{loading ? labels.loading : labels.empty}</output>
                  )}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </section>
  );
}

export function ProjectsPage({ className, ...props }: ProjectsPageProps) {
  return (
    <div className={cn(pageClass, className)}>
      <h1 className="sr-only">{props.labels?.title ?? projectLabels.title}</h1>
      <ProjectsList {...props} />
    </div>
  );
}

function ProjectDetailPageContent({
  project: suppliedProject,
  section = "details",
  backHref,
  sectionHrefs,
  onSave,
  onDelete,
  driveContent,
  className,
  labels: overrides,
  linkComponent: ProjectLink = Link,
}: ProjectDetailPageProps) {
  const labels = { ...projectLabels, ...overrides };
  const optimistic = useOptimisticAction(suppliedProject, suppliedProject.id);
  const project = optimistic.value;
  const website = safeProjectUrl(project.url);
  return (
    <div className={cn(pageClass, className)}>
      <ProjectLink
        href={backHref}
        className={cn(buttonClass, "hover:bg-primary/5 hover:text-primary")}
      >
        <ArrowLeftIcon aria-hidden="true" />
        {labels.back}
      </ProjectLink>
      <header className={cn(cardClass, "flex flex-wrap items-center gap-4")}>
        <ProjectAvatar name={project.name} image={project.posterImage} large />
        <div className="min-w-0 flex-1">
          <h1 className="text-xl font-semibold break-words">{project.name}</h1>
          <p className="text-sm break-all text-muted-foreground">
            {website ? (
              <ProjectLink
                href={website}
                className="hover:underline focus-visible:ring-2 focus-visible:ring-ring"
                target={website.startsWith("/") ? undefined : "_blank"}
                rel={website.startsWith("/") ? undefined : "noopener noreferrer"}
              >
                {website}
              </ProjectLink>
            ) : (
              labels.noWebsite
            )}
          </p>
        </div>
        <div className="ml-auto self-start">
          <ProjectStatusBadge status={project.status} labels={labels} />
        </div>
      </header>
      <nav aria-label={labels.sections} className="flex overflow-x-auto border-b border-border">
        {(["details", "drive"] as const).map((tab) => (
          <ProjectLink
            key={tab}
            href={sectionHrefs[tab]}
            aria-current={section === tab ? "page" : undefined}
            className={cn(
              "shrink-0 border-b-2 border-transparent px-4 py-2 text-sm font-semibold text-muted-foreground hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-inset",
              section === tab && "border-primary text-primary",
            )}
          >
            {labels[tab]}
          </ProjectLink>
        ))}
      </nav>
      {section === "details" ? (
        <ProjectForm
          key={project.id}
          project={project}
          labels={labels}
          onSubmit={(values) =>
            optimistic.run(
              (row) => ({ ...row, ...values }),
              () => onSave(values),
            )
          }
          onDelete={onDelete}
        />
      ) : (
        driveContent
      )}
    </div>
  );
}

export function ProjectNewPage({
  backHref,
  onCreate,
  className,
  labels: overrides,
  linkComponent: ProjectLink = Link,
}: ProjectNewPageProps) {
  const labels = { ...projectLabels, ...overrides };
  return (
    <div className={cn(pageClass, className)}>
      <ProjectLink
        href={backHref}
        className={cn(buttonClass, "hover:bg-primary/5 hover:text-primary")}
      >
        <ArrowLeftIcon aria-hidden="true" />
        {labels.back}
      </ProjectLink>
      <header className={cn(cardClass, "space-y-1.5")}>
        <h1 className="font-semibold">{labels.newTitle}</h1>
        <p className="text-sm text-muted-foreground">{labels.newDescription}</p>
      </header>
      <ProjectForm labels={labels} onSubmit={onCreate} />
    </div>
  );
}

export function ProjectsList(props: ProjectsListProps) {
  return (
    <ActionToastProvider>
      <ProjectsListContent {...props} />
    </ActionToastProvider>
  );
}

export function ProjectDetailPage(props: ProjectDetailPageProps) {
  return (
    <ActionToastProvider>
      <ProjectDetailPageContent {...props} />
    </ActionToastProvider>
  );
}

"use client";

import { useId, useRef, useState, type FormEvent } from "react";

import { ActionToastProvider } from "@/components/action-toast";
import { NativeSelect } from "@/components/native-select";
import {
  cardClass,
  Feedback,
  inputClass,
  primaryButtonClass,
  useCustomerAction,
} from "@/components/plugins/customers/ui";
import type { ProjectsLabels } from "@/components/plugins/projects/labels";
import type { Project, ProjectFormValues } from "@/components/plugins/projects/types";
import { DeleteProject } from "@/components/plugins/projects/ui";
import {
  projectFormValues,
  projectStatuses,
  validateProject,
} from "@/components/plugins/projects/utils";
import { cn } from "@/components/utils/cn";

export interface ProjectFormProps {
  className?: string;
  project?: Project;
  labels: ProjectsLabels;
  onSubmit: (values: ProjectFormValues) => Promise<void>;
  onDelete?: (id: string) => Promise<void>;
}

function ProjectFormContent({ project, labels, onSubmit, onDelete, className }: ProjectFormProps) {
  const id = `factory-project-form-${useId()}`;
  const formRef = useRef<HTMLFormElement>(null);
  const [values, setValues] = useState(() => projectFormValues(project));
  const [errors, setErrors] = useState<Partial<Record<keyof ProjectFormValues, string>>>({});
  const [deleting, setDeleting] = useState(false);
  const action = useCustomerAction(labels.actionError);
  const pending = action.pending || deleting;

  function change<K extends keyof ProjectFormValues>(name: K, value: ProjectFormValues[K]) {
    setValues((current) => ({ ...current, [name]: value }));
    setErrors((current) => ({ ...current, [name]: undefined }));
  }
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (pending) return;
    const normalized = {
      ...values,
      name: values.name.trim(),
      description: values.description.trim(),
    };
    const nextErrors = validateProject(normalized, labels);
    setErrors(nextErrors);
    const firstInvalid = Object.keys(nextErrors)[0];
    if (firstInvalid) {
      (event.currentTarget.elements.namedItem(firstInvalid) as HTMLElement | null)?.focus();
      return;
    }
    if (await action.run(() => onSubmit(normalized), project ? labels.saved : labels.created))
      setValues(normalized);
  }
  function error(name: keyof ProjectFormValues) {
    return errors[name] ? (
      <p id={`${id}-${name}-error`} role="alert" className="text-sm text-destructive">
        {errors[name]}
      </p>
    ) : null;
  }
  function fieldProps(name: keyof ProjectFormValues) {
    return {
      id: `${id}-${name}`,
      name,
      "aria-invalid": Boolean(errors[name]),
      "aria-describedby": errors[name] ? `${id}-${name}-error` : undefined,
      className: inputClass,
    };
  }
  return (
    <div className={className}>
      <form
        ref={formRef}
        tabIndex={-1}
        noValidate
        onSubmit={submit}
        aria-busy={pending}
        className={cn(cardClass, "space-y-5")}
      >
        {project && (
          <div className="space-y-1.5">
            <h2 className="font-semibold">{labels.detailsTitle}</h2>
            <p className="text-sm text-muted-foreground">{labels.detailsDescription}</p>
          </div>
        )}
        <fieldset disabled={pending} className="grid min-w-0 grid-cols-1 gap-5 md:grid-cols-2">
          <div className="space-y-2">
            <label htmlFor={`${id}-name`} className="block text-sm font-semibold">
              {labels.name} *
            </label>
            <input
              {...fieldProps("name")}
              required
              value={values.name}
              onChange={(event) => change("name", event.target.value)}
            />
            {error("name")}
          </div>
          <div className="space-y-2">
            <label htmlFor={`${id}-status`} className="block text-sm font-semibold">
              {labels.status}
            </label>
            <NativeSelect
              {...fieldProps("status")}
              value={values.status}
              onChange={(event) => {
                const status = projectStatuses.find((entry) => entry === event.target.value);
                if (status) change("status", status);
              }}
            >
              {projectStatuses.map((status) => (
                <option key={status} value={status}>
                  {labels[status]}
                </option>
              ))}
            </NativeSelect>
            {error("status")}
          </div>
          <div className="space-y-2 md:col-span-2">
            <label htmlFor={`${id}-description`} className="block text-sm font-semibold">
              {labels.projectDescription}
            </label>
            <textarea
              {...fieldProps("description")}
              className={cn(inputClass, "h-auto py-2")}
              rows={3}
              value={values.description}
              onChange={(event) => change("description", event.target.value)}
            />
            {error("description")}
          </div>
          <div className="flex justify-end md:col-span-2">
            <button type="submit" className={primaryButtonClass}>
              {pending ? labels.pending : project ? labels.save : labels.create}
            </button>
          </div>
        </fieldset>
        <Feedback feedback={action.feedback} />
      </form>
      {project && onDelete && (
        <div className="mt-6">
          <DeleteProject
            project={project}
            onDelete={onDelete}
            labels={labels}
            disabled={pending}
            onPendingChange={setDeleting}
            returnFocus={formRef}
          />
        </div>
      )}
    </div>
  );
}

export function ProjectForm(props: ProjectFormProps) {
  return (
    <ActionToastProvider>
      <ProjectFormContent {...props} />
    </ActionToastProvider>
  );
}

"use client";

import { Avatar } from "@base-ui/react/avatar";
import { Dialog } from "@base-ui/react/dialog";
import { Trash2Icon } from "lucide-react";
import { useRef, useState, type RefObject } from "react";

import {
  buttonClass,
  iconButtonClass,
  cardClass,
  Feedback,
  outlineButtonClass,
  useCustomerAction,
} from "@/components/plugins/customers/ui";
import { customerInitials } from "@/components/plugins/customers/utils";
import type { ProjectsLabels } from "@/components/plugins/projects/labels";
import type { Project, ProjectStatus } from "@/components/plugins/projects/types";
import { cn } from "@/components/utils/cn";

const popupClass = cn(
  cardClass,
  "fixed top-1/2 left-1/2 z-50 max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 space-y-5 overflow-y-auto shadow-xl",
);

export function ProjectAvatar({
  name,
  image,
  large = false,
}: {
  name: string;
  image?: string | null;
  large?: boolean;
}) {
  return (
    <Avatar.Root
      className={cn(
        "flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-full border border-border text-sm",
        large && "size-16 text-xl",
      )}
    >
      <Avatar.Image src={image ?? undefined} alt={name} className="size-full object-contain" />
      <Avatar.Fallback>{customerInitials(name, "")}</Avatar.Fallback>
    </Avatar.Root>
  );
}

export function ProjectStatusBadge({
  status,
  labels,
}: {
  status: ProjectStatus;
  labels: ProjectsLabels;
}) {
  return (
    <span
      className={cn(
        "inline-flex shrink-0 items-center gap-1.5 rounded-full px-2 py-0.5 text-xs font-medium before:size-1.5 before:shrink-0 before:rounded-full before:bg-current",
        status === "production"
          ? "bg-status-success text-status-success-foreground"
          : status === "under-construction"
            ? "bg-status-pending text-status-pending-foreground"
            : status === "prospect"
              ? "bg-status-info text-status-info-foreground"
              : "bg-status-not-started text-status-not-started-foreground",
      )}
    >
      {labels[status]}
    </span>
  );
}

export function DeleteProject({
  project,
  onDelete,
  labels,
  disabled,
  onPendingChange,
  returnFocus,
}: {
  project: Project;
  onDelete: (id: string) => Promise<void>;
  labels: ProjectsLabels;
  disabled?: boolean;
  onPendingChange?: (pending: boolean) => void;
  returnFocus?: RefObject<HTMLElement | null>;
}) {
  const [open, setOpen] = useState(false);
  const action = useCustomerAction(labels.actionError);
  const trigger = useRef<HTMLButtonElement>(null);
  return (
    <div>
      <Dialog.Root
        open={open}
        onOpenChange={(next) => {
          if (!action.pending) setOpen(next);
        }}
      >
        <Dialog.Trigger
          ref={trigger}
          disabled={disabled || action.pending}
          className={cn(
            iconButtonClass,
            "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
          )}
          aria-label={labels.deleteProject}
        >
          <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
        </Dialog.Trigger>
        <Dialog.Portal>
          <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
          <Dialog.Popup
            className={popupClass}
            finalFocus={() =>
              trigger.current?.isConnected ? trigger.current : (returnFocus?.current ?? true)
            }
          >
            <Dialog.Title className="text-lg font-semibold">{labels.deleteProject}</Dialog.Title>
            <Dialog.Description className="text-sm text-muted-foreground">
              {labels.deleteDescription(project.name)}
            </Dialog.Description>
            <Feedback feedback={action.feedback} />
            <div className="flex flex-wrap justify-end gap-2">
              <Dialog.Close disabled={action.pending} className={outlineButtonClass}>
                {labels.cancel}
              </Dialog.Close>
              <button
                type="button"
                disabled={disabled || action.pending}
                aria-busy={action.pending}
                className={cn(
                  buttonClass,
                  "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
                )}
                onClick={async () => {
                  const success = await action.run(async () => {
                    onPendingChange?.(true);
                    try {
                      await onDelete(project.id);
                    } finally {
                      onPendingChange?.(false);
                    }
                  }, labels.deleted);
                  if (success) {
                    setOpen(false);
                    if (!trigger.current?.isConnected) returnFocus?.current?.focus();
                  }
                }}
              >
                {action.pending ? labels.pending : labels.confirmDelete}
              </button>
            </div>
          </Dialog.Popup>
        </Dialog.Portal>
      </Dialog.Root>
      {!open && <Feedback feedback={action.feedback} />}
    </div>
  );
}

import type { ComponentType, ReactNode } from "react";

import type { LinkProps } from "@/components/link";
import type { Customer } from "@/components/plugins/customers";
import type { ProjectsLabels } from "@/components/plugins/projects/labels";

export type ProjectStatus = "requested" | "prospect" | "under-construction" | "production";
export type ProjectSection = "details" | "drive";

export interface Project {
  id: string;
  name: string;
  ownerId: Customer["id"];
  status: ProjectStatus;
  description?: string | null;
  url?: string | null;
  posterImage?: string | null;
  assigneeId?: string | null;
}

export interface ProjectFormValues {
  name: string;
  status: ProjectStatus;
  description: string;
}

export interface ProjectAssignee {
  id: string;
  name: string;
  email?: string | null;
  image?: string | null;
}

export interface ProjectsAppearanceProps {
  className?: string;
  labels?: Partial<ProjectsLabels>;
  linkComponent?: ComponentType<LinkProps>;
}

export interface ProjectsListProps extends ProjectsAppearanceProps {
  projects: readonly Project[];
  customers: readonly Customer[];
  assignees?: readonly ProjectAssignee[];
  customerId?: Customer["id"];
  search: string;
  onSearchChange: (search: string) => void;
  loading?: boolean;
  error?: string;
  createHref?: string;
  getProjectHref: (project: Project) => string;
  getCustomerHref?: (customer: Customer) => string;
  onDelete?: (projectId: string) => Promise<void>;
}

export type ProjectsPageProps = ProjectsListProps;

export interface ProjectDetailPageProps extends ProjectsAppearanceProps {
  project: Project;
  section?: ProjectSection;
  backHref: string;
  sectionHrefs: Record<ProjectSection, string>;
  onSave: (values: ProjectFormValues) => Promise<void>;
  onDelete?: (projectId: string) => Promise<void>;
  driveContent?: ReactNode;
}

export interface ProjectNewPageProps extends ProjectsAppearanceProps {
  backHref: string;
  onCreate: (values: ProjectFormValues) => Promise<void>;
}

import type { ProjectsLabels } from "@/components/plugins/projects/labels";
import type {
  Project,
  ProjectFormValues,
  ProjectStatus,
} from "@/components/plugins/projects/types";

export const projectStatuses: readonly ProjectStatus[] = [
  "requested",
  "prospect",
  "under-construction",
  "production",
];

export function projectFormValues(project?: Project): ProjectFormValues {
  return {
    name: project?.name ?? "",
    status: project?.status ?? "requested",
    description: project?.description ?? "",
  };
}

export function safeProjectUrl(input: string | null | undefined): string | undefined {
  const value = input?.trim();
  // oxlint-disable-next-line no-control-regex -- Reject controls before URL normalization.
  if (!value || value.length > 2048 || /[\\\u0000-\u0020\u007f]/.test(value)) return undefined;
  if (value.startsWith("/") && !value.startsWith("//")) return value;
  if (!/^https?:\/\//i.test(value)) return undefined;
  try {
    const url = new URL(value);
    return url.hostname && !url.username && !url.password ? value : undefined;
  } catch {
    return undefined;
  }
}

export function validateProject(values: ProjectFormValues, labels: ProjectsLabels) {
  const errors: Partial<Record<keyof ProjectFormValues, string>> = {};
  if (!values.name.trim()) errors.name = labels.nameRequired;
  if (!projectStatuses.includes(values.status)) errors.status = labels.statusInvalid;
  if (values.description.trim().length > 5000) errors.description = labels.descriptionInvalid;
  return errors;
}
